mapper.sql:
select T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T8.REAL_NAME invManagerId, T1.PORTFOLIO_ID portfolioId,
T2.PORTFOLIO_NAME portfolioName, T7.TERM_TYPE termType, T7.TERM_DAYS repoTerm, T1.PS ps, T1.ENTRUST_AMT entrustAmt, T1.PRICE_MODEL priceModel, T1.PRICE*100 price, T7.SETTLE_SPREED settleSpreed, T1.VDATE vdate, T1.MDATE mdate, NVL(T5.FINISH_AMT,0) finishAmt, round(NVL(T5.FINISH_AMT,0)/(T1.ENTRUST_AMT),4)*100 transactioncom, T1.REMARK from ETR_ENTRUST T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON T1.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId} INNER JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM( FINISH_AMT) as FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN SYS_USER T8 ON T1.INV_MANAGER_ID = T8.USER_NAME where T1.FINPROD_TYPE2 in (#{FINPROD_TYPE2_Z},#{FINPROD_TYPE2_N}) and T1.TRADE_MARKET = #{TRADE_PLACE_01}

select T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T8.REAL_NAME invManagerId, T1.PORTFOLIO_ID portfolioId,
T2.PORTFOLIO_NAME portfolioName, T7.TERM_TYPE termType, T7.TERM_DAYS repoTerm, T1.PS ps, T1.ENTRUST_AMT entrustAmt, T1.PRICE_MODEL priceModel, T1.PRICE*100 price, T7.SETTLE_SPREED settleSpreed, T1.VDATE vdate, T1.MDATE mdate, NVL(T5.FINISH_AMT,0) finishAmt, round(NVL(T5.FINISH_AMT,0)/(T1.ENTRUST_AMT),4)*100 transactioncom, T1.REMARK from WFL_ETR_ENTRUST T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON T1.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
INNER JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) as FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN WFL_ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN SYS_USER T8 ON T1.INV_MANAGER_ID = T8.USER_NAME where T1.FINPROD_TYPE2 in (#{FINPROD_TYPE2_Z},#{FINPROD_TYPE2_N}) and T1.TRADE_MARKET = #{TRADE_PLACE_01}

mapper.select:
SELECT TABLE01.PORTFOLIO_ID portfolioId,/*组合代码*/ TABLE01.PORTFOLIO_NAME portfolioName, TABLE01.SEC_ACCT_ID secAcctId,/*证券账户/通道代码*/ TABLE01.FINPROD_ID finProdId,/*金融产品Id*/ TABLE01.BRANCH branch,/*分支序号*/ NVL(TABLE02.AMOUNT,0) / 100 posStrdPrinAmt,/*持仓券面总额*/ NVL(TABLE01.AMOUNT,0) / 100 pledStrdPrinAmt,/*可质押券面总额*/ ETR_ENTRUST_PLEDGE.SCALE scale, /*折算比例*/ ETR_ENTRUST_PLEDGE.PLEDGE_STOCK_ID pledgeStockId,/*质押库代码*/ FIN_PRODUCT.MDATE mdate,/*到期日*/ MBCR.GRADE_RESULT gradeResult,/*债项评级*/ FIN_PRODUCT.REGIST_ORG registOrg,/*登记托管机构*/ NVL(FIN_PRODUCT.FINPROD_ABBR,FIN_PRODUCT.FINPROD_NAME) finProdName,/*金融产品名称*/ MST_BOND_VALUATION_INFO.LAST_PERIOD lastPeriod,/*剩余期限*/ FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId,/*市场代码*/ CASE WHEN FIN_PRODUCT2.IS_CHL = 'Y' THEN FIN_PRODUCT2.FINPROD_NAME ELSE STL_SEC_ACCT_INFO.SEC_ACCT_NAME END AS secAcctStr ,TABLE01.parentPortfolioId, ETR_SEC_STOCK.PLEDGE_STOCK_NAME FROM ETR_ENTRUST_PLEDGE left join ETR_SEC_STOCK on ETR_SEC_STOCK.PLEDGE_STOCK_ID=ETR_ENTRUST_PLEDGE.PLEDGE_STOCK_ID LEFT JOIN ( SELECT TEMP.PORTFOLIO_ID,/*组合代码*/ TEMP.parentPortfolioId, TEMP.PORTFOLIO_NAME, TEMP.SEC_ACCT_ID,/*证券账户/通道代码*/ TEMP.FINPROD_ID,/*金融产品Id*/ TEMP.BRANCH,/*分支序号*/ SUM(TEMP.AMOUNT) AMOUNT /*可质押券面总额*/ FROM ( SELECT NVL(T2.PARENT_PORTFOLIO_ID, T2.PORTFOLIO_ID) parentPortfolioId, PTL_SEC_POSITION.PORTFOLIO_ID, T2.PORTFOLIO_NAME, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05},#{POSITION_TYPE_08})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION INNER JOIN PTL_PORTFOLIO T2 ON PTL_SEC_POSITION.PORTFOLIO_ID = T2.PORTFOLIO_ID WHERE 1=1 AND PTL_SEC_POSITION.CDATE = to_date(#{sysDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：03实际，04质押，05融入，06融出，08预占用,11卖空*/ AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_08},#{POSITION_TYPE_11})
UNION ALL SELECT NVL(T2.PARENT_PORTFOLIO_ID, T2.PORTFOLIO_ID) parentPortfolioId, PTL_SEC_POSITION_FLOW.PORTFOLIO_ID, T2.PORTFOLIO_NAME, PTL_SEC_POSITION_FLOW.SEC_ACCT_ID, PTL_SEC_POSITION_FLOW.FINPROD_ID, PTL_SEC_POSITION_FLOW.BRANCH, CASE WHEN PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01})then PTL_SEC_POSITION_FLOW.AMOUNT ELSE -1 * PTL_SEC_POSITION_FLOW.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION_FLOW INNER JOIN PTL_PORTFOLIO T2 ON PTL_SEC_POSITION_FLOW.PORTFOLIO_ID = T2.PORTFOLIO_ID WHERE 1=1 AND PTL_SEC_POSITION_FLOW.CDATE = to_date(#{sysDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：01可用，12卖空可用*/ AND PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_12}) ) TEMP
LEFT JOIN PTL_PORTFOLIO_AUTHORITY on TEMP.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE 1=1 AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} GROUP BY TEMP.PORTFOLIO_ID, TEMP.parentPortfolioId, TEMP.PORTFOLIO_NAME, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.PORTFOLIO_ID, TEMP.BRANCH HAVING SUM(TEMP.AMOUNT) > 0/*只统计可质押券面总额>0*/ )TABLE01/*以上统计可用持仓*/ ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = TABLE01.PORTFOLIO_ID AND ETR_ENTRUST_PLEDGE.FINPROD_ID = TABLE01.FINPROD_ID AND ETR_ENTRUST_PLEDGE.BRANCH = TABLE01.BRANCH AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = TABLE01.SEC_ACCT_ID LEFT JOIN ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, SUM( CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END) as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = to_date(#{sysDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：03实际，05融入，06融出,11卖空*/ AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_11}) GROUP BY PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.BRANCH )TABLE02 /*以上统计实际持仓*/ ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = TABLE02.PORTFOLIO_ID AND ETR_ENTRUST_PLEDGE.FINPROD_ID = TABLE02.FINPROD_ID AND ETR_ENTRUST_PLEDGE.BRANCH = TABLE02.BRANCH AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = TABLE02.SEC_ACCT_ID INNER JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TABLE01.FINPROD_ID
AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
LEFT JOIN STL_SEC_ACCT_INFO on TABLE01.SEC_ACCT_ID = STL_SEC_ACCT_INFO.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FIN_PRODUCT2 on TABLE01.SEC_ACCT_ID = FIN_PRODUCT2.FINPROD_ID LEFT JOIN ( SELECT T2.SEC_ID, T2.LAST_PERIOD FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{sysDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = #{VALUATION_SOURCE_CBC} GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) MST_BOND_VALUATION_INFO ON FIN_PRODUCT.FINPROD_MARKET_ID = MST_BOND_VALUATION_INFO.SEC_ID /*以上获取债券小于等于平台日的最新估值行情*/ LEFT JOIN (SELECT RANK() OVER(PARTITION BY O_CODE ORDER BY GRADE_DATE DESC,CAST(GRADE_RESULT AS DECIMAL) DESC) NUM, O_CODE, GRADE_RESULT FROM MST_BOND_CREDIT_RATING WHERE GRADE_DATE <= to_date(#{sysDate},'yyyy-MM-dd') and GRADE_ORG_ID !='22') MBCR ON MBCR.O_CODE = FIN_PRODUCT.FINPROD_MARKET_ID AND MBCR.NUM = 1 WHERE 1=1 /*只获取交易场所为：01银行间*/ AND FIN_PRODUCT.TRADE_MARKET = #{TRADEPLACE01}
AND ETR_ENTRUST_PLEDGE.PORTFOLIO_ID in
#{item}
AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID in
#{item}
AND ETR_ENTRUST_PLEDGE.PLEDGE_STOCK_ID in
#{item}

select tb.id id, tb.text text from( SELECT DISTINCT A.ACCT_NO id, B.SEC_ACCT_NAME text FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
UNION ALL SELECT FINPROD_ID id , FINPROD_NAME text FROM FIN_PRODUCT
and ( FINPROD_MARKET_ID like concat(concat('%',#{search}),'%') or FINPROD_NAME like concat(concat('%',#{search}),'%') )
AND FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
)tb

select count(1)
	from ETR_SEC_STOCK
where PLEDGE_STOCK_NAME = #{pledgeStockName}

	 and  PLEDGE_STOCK_ID <> #{seqno}

select count(1)
	from ETR_SEC_STOCK_CONFIG
where PLEDGE_STOCK_ID = #{pledgeStockId}

        SELECT distinct
	        grp.PORTFOLIO_ID portfolioId,
	        grp.PORTFOLIO_NAME portfolioName
      FROM ptl_Portfolio grp
      LEFT JOIN PA_PTL_PORTFOLIO T2
		ON
		grp.PORTFOLIO_ID = T2.PORTFOLIO_ID

           left join PTL_SEC_STOCK psc on psc.PORTFOLIO_ID = grp.PORTFOLIO_ID

        where 1=1 and grp.PORTFOLIO_TYPE in ('01','03')

            AND grp.portfolio_id in

                #{item}



           and psc.PLEDGE_STOCK_ID = #{pledgeStockId}


           and grp.PROFIT_TYPE = #{profitType}


           and T2.OPEN_TYPE = #{openType}


           and T2.RAISE_TYPE = #{raiseType}


           and T2.INVEST_NATURE = #{investNature}

			AND grp.PORTFOLIO_ID    IN
			  (SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{username}
			  )

mapper.delete:
delete from ETR_ENTRUST_PLEDGE
where PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
  and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and BRANCH = #{branch,jdbcType=DECIMAL}
  and SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
  and PLEDGE_STOCK_ID = #{pledgeStockId,jdbcType=VARCHAR}

mapper.select:
SELECT T.ACCT_NO FROM PTL_CAPACCT_INFO T 
	WHERE T.ACCT_TYPE ='A01' 
		AND T.PORTFOLIO_ID=#{portfolioId,jdbcType=VARCHAR}

SELECT TABLE01.PORTFOLIO_ID portfolioId,/*组合代码*/ TABLE01.SEC_ACCT_ID secAcctId,/*证券账户/通道代码*/ -- NVL(FIN_PRODUCT.FINPROD_NAME,STL_SEC_ACCT_INFO.SEC_ACCT_NAME) secAcctStr,/*证券账户/通道代码*/ TABLE01.FINPROD_ID finProdId,/*金融产品Id*/ FIN_PRODUCT.FINPROD_ABBR finProdAbbr,/*金融产品简称*/ FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId,/*金融产品市场代码*/ TABLE01.BRANCH branch,/*分支序号*/ NVL(TABLE01.AMOUNT,0) * 100 pledStrdPrinAmt,/*可质押券面总额*/ NVL(TABLE02.AMOUNT,0) * 100 posStrdPrinAmt,/*持仓券面总额*/ FIN_PRODUCT.TRADE_MARKET tradePlace,/*交易场所*/ FIN_PRODUCT.MDATE mdate,/*到期日*/ MST_BOND_VALUATION_INFO.LAST_PERIOD lastPeriod,/*剩余期限*/ MBCR.GRADE_RESULT gradeResult,/*债项评级*/ FIN_PRODUCT.REGIST_ORG registOrg,/*登记托管机构*/ NVL(fscr.SCALE, 1)*100 scale, /*折算比例*/ FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId,/*市场代码*/ FIN_PRODUCT.ISSUER issuer, /*发行人*/ CASE WHEN FIN_PRODUCT2.IS_CHL = 'Y' THEN FIN_PRODUCT2.FINPROD_NAME ELSE STL_SEC_ACCT_INFO.SEC_ACCT_NAME END AS secAcctStr FROM ( SELECT TEMP.PORTFOLIO_ID,/*组合代码*/ TEMP.SEC_ACCT_ID,/*证券账户/通道代码*/ TEMP.FINPROD_ID,/*金融产品Id*/ TEMP.BRANCH,/*分支序号*/ SUM(TEMP.AMOUNT) AMOUNT /*可质押券面总额*/ FROM ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05},#{POSITION_TYPE_08})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = to_date(#{sysDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：03实际，04质押，05融入，06融出，08预占用,11卖空*/ AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_08},#{POSITION_TYPE_11})
UNION ALL SELECT PTL_SEC_POSITION_FLOW.PORTFOLIO_ID, PTL_SEC_POSITION_FLOW.SEC_ACCT_ID, PTL_SEC_POSITION_FLOW.FINPROD_ID, PTL_SEC_POSITION_FLOW.BRANCH, CASE WHEN PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01})then PTL_SEC_POSITION_FLOW.AMOUNT ELSE -1 * PTL_SEC_POSITION_FLOW.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION_FLOW WHERE 1=1 AND PTL_SEC_POSITION_FLOW.CDATE = to_date(#{sysDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：01可用，12卖空可用*/ AND PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_12}) ) TEMP LEFT JOIN PTL_PORTFOLIO_AUTHORITY on TEMP.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE 1=1 AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} GROUP BY TEMP.PORTFOLIO_ID, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.PORTFOLIO_ID, TEMP.BRANCH HAVING SUM(TEMP.AMOUNT) > 0/*只统计可质押券面总额>0*/ )TABLE01/*以上统计可用持仓*/ LEFT JOIN STL_SEC_ACCT_INFO on TABLE01.SEC_ACCT_ID = STL_SEC_ACCT_INFO.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FIN_PRODUCT2 on TABLE01.SEC_ACCT_ID = FIN_PRODUCT2.FINPROD_ID LEFT JOIN ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, SUM( CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END) as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = to_date(#{sysDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：03实际，05融入，06融出,11卖空*/ AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_11}) GROUP BY PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.BRANCH )TABLE02 /*以上统计实际持仓*/ ON TABLE01.PORTFOLIO_ID = TABLE02.PORTFOLIO_ID AND TABLE01.SEC_ACCT_ID = TABLE02.SEC_ACCT_ID AND TABLE01.FINPROD_ID = TABLE02.FINPROD_ID AND TABLE01.BRANCH = TABLE02.BRANCH INNER JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TABLE01.FINPROD_ID LEFT JOIN ( SELECT T2.SEC_ID, T2.LAST_PERIOD FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{sysDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = #{VALUATION_SOURCE_CBC} GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) MST_BOND_VALUATION_INFO/*以上获取债券小于等于平台日的最新估值行情*/ ON FIN_PRODUCT.FINPROD_MARKET_ID = MST_BOND_VALUATION_INFO.SEC_ID LEFT JOIN FIN_STDSEC_CONVERSE_RADIO fscr ON fscr.FINPROD_ID = TABLE01.FINPROD_ID AND fscr.BRANCH = TABLE01.BRANCH AND fscr.VDATE <= to_date(#{sysDate}, 'yyyy-MM-dd') AND NOT EXISTS ( SELECT * FROM FIN_STDSEC_CONVERSE_RADIO fscrInner WHERE fscrInner.FINPROD_ID = fscr.FINPROD_ID AND fscrInner.BRANCH = fscr.BRANCH AND fscrInner.VDATE <= to_date(#{sysDate}, 'yyyy-MM-dd') AND fscrInner.VDATE > fscr.VDATE ) LEFT JOIN (SELECT RANK() OVER(PARTITION BY O_CODE ORDER BY GRADE_DATE DESC,CAST(GRADE_RESULT AS DECIMAL) DESC) NUM, O_CODE, GRADE_RESULT FROM MST_BOND_CREDIT_RATING WHERE GRADE_DATE <= to_date(#{sysDate},'yyyy-MM-dd') and GRADE_ORG_ID !='22' ) MBCR ON MBCR.O_CODE = FIN_PRODUCT.FINPROD_MARKET_ID AND MBCR.NUM = 1 LEFT JOIN FIN_PRODUCT_ADD FPA ON FIN_PRODUCT.FINPROD_ID = FPA.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = FIN_PRODUCT.FINPROD_ID WHERE 1=1 AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} /*只获取交易场所为：01银行间，03上海证券交易所,04深圳证券交易所*/ AND FIN_PRODUCT.TRADE_MARKET = #{TRADEPLACE01}
AND (TABLE01.PORTFOLIO_ID in
null) or TABLE01.PORTFOLIO_ID in (
#{item}
)
AND T4.TYPE_9 = #{windtypeone,jdbcType=VARCHAR}
AND T4.TYPE_10 = #{windtypetwo,jdbcType=VARCHAR}
AND FPA.IS_SEC_BOND = #{isSecBond,jdbcType=VARCHAR}
AND FIN_PRODUCT.IS_RIGHT = #{isRight,jdbcType=VARCHAR}
AND FPA.IS_PPB = #{isPpb,jdbcType=VARCHAR}
